trim.if:
SELECT 'heritage_project' AS type, hp.id, hp.name AS title, hp.cover, hp.description AS summary, COALESCE(hc.name, hp.category) AS category, hp.level_code AS level_code, hp.region_code AS region_code, NULL AS price, NULL AS start_time, hp.recommend_sort AS sort_value FROM heritage_project hp LEFT JOIN category hc ON hc.id = hp.category_id AND hc.biz_type = 'HERITAGE' WHERE hp.status = 1 AND ( hp.name LIKE CONCAT('%', #{keyword}, '%') OR hp.description LIKE CONCAT('%', #{keyword}, '%') OR hp.category LIKE CONCAT('%', #{keyword}, '%') OR hp.region LIKE CONCAT('%', #{keyword}, '%') OR hp.official_code LIKE CONCAT('%', #{keyword}, '%') )
AND hp.category_id = #{categoryId}
AND hp.level_code = #{levelCode}
AND hp.region_code = #{regionCode}
UNION ALL

SELECT 'course' AS type, c.id, c.title, c.cover, COALESCE(c.summary, c.description) AS summary, cc.name AS category, NULL AS level_code, c.city_code AS region_code, c.price, ( SELECT MIN(cs.start_time) FROM course_session cs WHERE cs.course_id = c.id AND cs.status = 1 AND cs.start_time >= NOW() ) AS start_time, c.recommend_sort AS sort_value FROM course c LEFT JOIN category cc ON cc.id = c.category_id WHERE c.audit_status = 1 AND c.publish_status = 1 AND ( c.title LIKE CONCAT('%', #{keyword}, '%') OR c.summary LIKE CONCAT('%', #{keyword}, '%') OR c.description LIKE CONCAT('%', #{keyword}, '%') OR cc.name LIKE CONCAT('%', #{keyword}, '%') )
AND c.category_id = #{categoryId}
AND 1 = 0
AND c.city_code = #{regionCode}
UNION ALL
